import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"实时推送","description":"","frontmatter":{},"headers":[],"relativePath":"backend/realtime.md","filePath":"backend/realtime.md","lastUpdated":1794049926000}`),a={name:`backend/realtime.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="实时推送" tabindex="-1">实时推送 <a class="header-anchor" href="#实时推送" aria-label="Permalink to “实时推送”">​</a></h1><p>本页说明 Hub 的登记、推送方法、推送契约、在线状态与跨实例，适用于后端开发者。</p><div class="info custom-block"><p class="custom-block-title">本页范围</p><p>通知 Hub（强制下线、站内通知、任务进度、跨端设置同步）、在线状态与配了 Redis 时的跨实例由 Realtime 包提供；聊天 Hub <code>/hubs/chat</code> 由 Chat 包登记，会话、消息与聊天专用的推送方法见<a href="./chat">在线聊天</a>。</p></div><p>实时能力由 Realtime 包（Tier 2）提供：直接用 ASP.NET Core SignalR，其他包只经 <code>Contracts</code> 的接口（<code>IRealtimePush</code>、<code>IRealtimePresence</code>）使用它。没装 Realtime 即没有推送，各包照常工作。</p><h2 id="hub" tabindex="-1">Hub <a class="header-anchor" href="#hub" aria-label="Permalink to “Hub”">​</a></h2><p>Realtime 自己登记通知 Hub，别的包的 Hub 继承 <code>RealtimeHub</code> 并在自己的 Feature 里 <code>AddRealtimeHub&lt;THub&gt;(路径)</code> 登记，宿主的 <code>MapRealtimeHubs()</code> 把登记过的 Hub 一并映射（包没装配即不映射）。路径必须在 <code>/hubs</code> 下，同一路径或类型重复登记即启动失败。</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>地址</td><td><code>/hubs/notification</code>；各包登记的 Hub（如 Chat 的 <code>/hubs/chat</code>）</td></tr><tr><td>认证</td><td>绕过内核管道（<code>BypassXiHanPipeline</code>）；用 ASP.NET Core 认证的 XiHan 方案，与 <code>Security.Jwt</code> 同一套参数（密钥、签发者、受众、容差、不映射入站声明）</td></tr><tr><td>令牌</td><td>只在 <code>/hubs</code> 下从查询串 <code>access_token</code> 读</td></tr><tr><td>会话门禁</td><td><code>SessionAuthenticationFilter</code> 同样核对会话有效，吊销的会话连不上</td></tr></tbody></table><p>连接建立后按会话、用户、用户在当前一侧、当前一侧加入各组，再登记连接（在线状态显示为在线时一定已经收得到推送）；推送按组发出。派生的 Hub 要让连接另外加入组时用 <code>JoinGroupAsync</code>，吊销会话时这些组一并移出。</p><h2 id="推送方法" tabindex="-1">推送方法 <a class="header-anchor" href="#推送方法" aria-label="Permalink to “推送方法”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>谁发</th><th>内容</th></tr></thead><tbody><tr><td><code>ForceLogout</code></td><td>Identity</td><td>会话被吊销（强制下线、改密、锁定、停用、删除），带给用户看的原因</td></tr><tr><td><code>ReceiveNotification</code></td><td>Notification</td><td>发布或提醒时按接收人推送</td></tr><tr><td><code>TaskProgress</code></td><td>Files、Notification</td><td>导出任务与通知发布的进度，只推给发起人，见<a href="#任务进度">任务进度</a></td></tr><tr><td><code>UserSettingChanged</code></td><td>Identity</td><td>个人设置在其他设备上改了（偏好、收藏、看板布局跨端同步）</td></tr><tr><td><code>ReceiveChatMessage</code> 等</td><td>Chat</td><td>聊天 Hub 上的消息、撤回、编辑、回应、已读位、会话变更与正在输入，见<a href="./chat#推送">在线聊天</a></td></tr></tbody></table><p>方法清单由 <code>contracts export</code> 一并导出为 <code>frontend/contracts/realtime.json</code>，前端生成 <code>packages/contracts/realtime.ts</code>。推送载荷是各包自己的记录，按各包的源生成序列化上下文序列化（枚举按名称）。</p><h2 id="推送契约" tabindex="-1">推送契约 <a class="header-anchor" href="#推送契约" aria-label="Permalink to “推送契约”">​</a></h2><div class="language-csharp"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Contracts：IRealtimePush</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> push.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SendAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(RealtimeHubs.Notification, RealtimeAudience.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UsersIn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(side, userIds), RealtimeMethods.ReceiveNotification, payload, jsonTypeInfo, cancellationToken);</span></span></code></pre></div><table tabindex="0"><thead><tr><th>受众</th><th>说明</th></tr></thead><tbody><tr><td><code>Sessions(ids)</code></td><td>指定会话（访问令牌的 <code>sid</code>）上的连接</td></tr><tr><td><code>UsersIn(side, ids)</code></td><td>用户在某一侧的连接：同一个人切到别的租户时收不到</td></tr><tr><td><code>Users(ids)</code></td><td>用户的全部连接，不分侧</td></tr><tr><td><code>Side(side)</code></td><td>平台或某个租户的全部在线连接</td></tr></tbody></table><p>第一个参数是 Hub 路径，没登记的 Hub 在调用里即抛出。</p><p>提交后才发：在调用管道里（操作、按租户执行的后台调用）先暂存，<code>RealtimeDispatchMiddleware</code> 在调用成功且事务提交之后才发出，失败或回滚即丢弃；管道外的后台循环立即发出。推送不保证送达：接收者此刻没有连接即略过，持久的状态（收件箱、任务进度）由各包自己的表承担。</p><p>立即推送 <code>SendNowAsync</code> 给不落库的瞬时事件（正在输入、助手的流式增量）：不等提交、不随回滚撤回。操作都有工作单元，但事务到第一次写入才开：写入之前可以立即推送，事务开了之后调用即抛出 <code>InvalidOperationException</code>。</p><p>吊销会话时先推 <code>ForceLogout</code>，再经 <code>DisconnectAsync</code>（发出时机同 <code>SendAsync</code>）把连接移出全部组、宽限 2 秒后断开，任一 Hub 上的连接都算。</p><h2 id="任务进度" tabindex="-1">任务进度 <a class="header-anchor" href="#任务进度" aria-label="Permalink to “任务进度”">​</a></h2><p><code>TaskProgress</code> 的载荷是 Contracts 的 <code>TaskProgressPayload</code>，推给发起人在任务那一侧的连接（<code>UsersIn(side, [发起人])</code>，切到别的租户收不到），前端灵动岛按 <code>taskId</code> 复用同一条，进行中常驻，成功或失败后自动收起。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>taskId</code></td><td>任务标识：导出是 <code>export:&lt;任务 ID&gt;</code>，通知发布是 <code>notification-publish:&lt;trace-id&gt;</code></td></tr><tr><td><code>label</code> / <code>detail</code></td><td>文案与副文本，服务端按发起人的区域翻好</td></tr><tr><td><code>state</code></td><td><code>loading</code>、<code>success</code> 或 <code>error</code></td></tr><tr><td><code>progress</code></td><td>进度 0 到 100，为空是不确定态</td></tr><tr><td><code>link</code></td><td>点击跳转的路由（导出中心、通知公告）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>任务</th><th>什么时候推</th><th>怎么发出</th></tr></thead><tbody><tr><td>导出</td><td>领到任务（准备中，进度 0）；每写一千行或到 99%（已写行数）；完成（总行数，点击去导出中心）；失败（失败原因）</td><td>随写任务表的那次调用提交后发出，失败走独立的短事务后立即发出。文案按提交时 <code>Accept-Language</code> 协商出的区域</td></tr><tr><td>通知发布（<code>notifications.publish</code>）</td><td>开始（不确定态）；成功（接收人数，点击去通知公告）；失败（失败原因，异常时没有原因）</td><td>成功随提交发出。开始与失败不随事务生效，由 Transaction 阶段开头、工作单元之外的 <code>PublishProgressMiddleware</code> 立即发出，回滚、提交失败与异常都会收尾</td></tr></tbody></table><p>建好即发布的 <code>notifications.create</code> 不推进度。</p><h2 id="hub-参数" tabindex="-1">Hub 参数 <a class="header-anchor" href="#hub-参数" aria-label="Permalink to “Hub 参数”">​</a></h2><p>保活、超时、消息大小等参数在配置节 <code>BasicApp:Realtime:SignalR</code>，对全部 Hub 生效，见<a href="./../configuration#basicapp-realtime-signalr">配置参考</a>。</p><h2 id="在线状态" tabindex="-1">在线状态 <a class="header-anchor" href="#在线状态" aria-label="Permalink to “在线状态”">​</a></h2><p><code>Contracts</code> 的在线状态接口（Realtime 实现）回答「哪些会话此刻持有实时连接」「某一侧有多少在线用户」：</p><ul><li>在线用户页（<code>sessions.list</code>）标出实时在线的会话；</li><li>工作台的在线设备、访问概况小组件。</li></ul><p>任一 Hub 上的连接都算在线。</p><h2 id="跨实例" tabindex="-1">跨实例 <a class="header-anchor" href="#跨实例" aria-label="Permalink to “跨实例”">​</a></h2><p>宿主配了 Redis（绑定 <code>cache</code>）即以跨实例装配 Realtime，没配全部在本实例内：</p><table tabindex="0"><thead><tr><th>方面</th><th>不配 Redis</th><th>配了 Redis</th></tr></thead><tbody><tr><td>推送与组</td><td>进程内</td><td>SignalR 接 Redis 背板：一个实例发出的推送送到各实例上的连接；背板用自己的连接，配置与账号取宿主的 Redis 缓存配置，频道带同一键前缀（<code>XiHan:Caching:Redis:KeyPrefix</code> + <code>realtime:</code>）</td></tr><tr><td>在线状态</td><td>本实例的连接登记</td><td>每个实例把自己的连接快照写进共享缓存（<code>realtime:presence:node:&lt;实例&gt;</code>），连接变化即重新写入，每 15 秒心跳续期、45 秒没续即过期；实例名册 <code>realtime:presence:nodes</code> 记各实例。读在线状态时汇总名册里未过期实例的快照</td></tr><tr><td>强制下线</td><td>移出组后断开本实例的连接</td><td>本实例的连接直接断开；别的实例上的连接经背板移出全部组（之后的推送不再送到），再以广播订阅 <code>basicapp.realtime.disconnect</code> 通知各实例断开自己的连接</td></tr></tbody></table><p>广播要经消息代理：只配了 Redis、没配 RabbitMQ 时广播只到本实例，别的实例上被吊销的连接只是被移出全部组、不再收到推送，等客户端收到 <code>ForceLogout</code> 自行断开或令牌过期——这是写明的语义，不是兜底。写共享缓存失败只记 Warning，在线状态等下一次心跳修复，不影响连接本身。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./chat">在线聊天</a> · <a href="./messaging">消息通知</a> · <a href="./../frontend/realtime">前端实时通信</a> · <a href="./authentication">统一认证</a></li></ul>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};